	public static void DrawTextOnPath(Graphics g, TextPathData textPath) {		var gp  = textPath.Path;		var str =  textPath.Text;		var fnt =  textPath.Font;		var clr = textPath.ForeColor;		var flatness = textPath.Flateness;		var gap = textPath.GapsSize;		const float to_degrees = (float)(180.0 / Math.PI);		// SUB: Draws a string that has been fitted to a base curve defined inside the graphicspath		// the effect is similar to WordArt in MS Word.  This assumes that there is a curve in the path object.		float x, y, dx, dy;		char[] letters = str.ToCharArray();		float fontScale = fnt.Size * fnt.FontFamily.GetCellAscent(fnt.Style) / fnt.FontFamily.GetEmHeight(fnt.Style);		var m = new Matrix();		// break up the smooth curve into a sequence of straight lines (tight curves may become jagged)		gp.Flatten(m, flatness);        // the matrix is just a default one		// create polyline from points		var pline = new Polyline2D(gp.PathPoints.ToList());		//// TEST - draw points on path ////		//Point lastPoint = Point.Empty;		//points.ForEach(p => {		//	var nextPoint = new Point((int)p.X, (int)p.Y);		//	g.DrawEllipse(new Pen(Color.Yellow), new Rectangle(nextPoint.X - 5, nextPoint.Y - 5, 10, 10));		//	if (!lastPoint.IsEmpty) g.DrawLine(new Pen(Color.Red), lastPoint.X, lastPoint.Y, nextPoint.X, nextPoint.Y);		//	lastPoint = nextPoint;		//});		/*Console.WriteLine("DrawFactory > DrawTextOnPath > DRAW TEST:");		Point lastPoint = Point.Empty;		var totalDistance = 0.0;		var nextPoint = pline.GetPointAtDistance(totalDistance);		var points = new List<PointF>();		while (!nextPoint.IsEmpty) {			points.Add(nextPoint);			g.DrawEllipse(new Pen(Color.Yellow), new Rectangle((int)nextPoint.X - 5, (int)nextPoint.Y - 5, 10, 10));			if (!lastPoint.IsEmpty) g.DrawLine(new Pen(Color.Red), lastPoint.X, lastPoint.Y, nextPoint.X, nextPoint.Y);			lastPoint = nextPoint.ToPoint();			totalDistance += 10.0;			nextPoint = pline.GetPointAtDistance(totalDistance);			Console.WriteLine("\ttotalDistance:{0} nextPoint:{1} empty:{2}", totalDistance, nextPoint, nextPoint.IsEmpty);		}*/		Brush textBrush = new SolidBrush(clr);		var dist = 0.0;		float scale = 0f;		letters.ForEach((l, i) => {			var letterWidth = g.MeasureString(l.ToString(), fnt).Width;			var p1 = pline.GetPointAtDistance(dist);			var p2 = pline.GetPointAtDistance(dist+letterWidth);			if (!p1.IsEmpty) {				dist += letterWidth / 2 + gap;				x = p1.X;				y = p1.Y;				// find the normal by swapping the coords and negating the final y value				dx = p2.Y - y;				dy = x - p2.X;				// change the dx,dy vector into a unit vector ("normalize" the normal)				scale = fontScale / (float)Math.Sqrt((double)(dx * dx + dy * dy));				dx *= scale;				dy *= scale;				m.Reset();				m.Translate(x + dx, y + dy);                // position the character															// rotate the character to align it to the curve				m.Rotate((float)(Math.Atan2((double)dy, (double)dx) * to_degrees + 90d));				g.Transform = m;               // apply the transformation to the g surface											   // draw a single character onto the g surface				g.DrawString(l.ToString(), fnt, textBrush, 0, 0);			}		});		g.ResetTransform();	}/// <summary>/// @by wossname; Jan 1st, 2006 at 09:19 AM./// </summary>/// <param name="g"></param>/// <param name="gp"></param>/// <param name="str"></param>/// <param name="fnt"></param>/// <param name="clr"></param>/// <param name="flatness">maximum distance between the flattened path and the original path.</param>public static void DrawTextOnPath_Old(Graphics g, TextPathData textPath) {	var gp  = textPath.Path;	var str =  textPath.Text;	var fnt =  textPath.Font;	var clr = textPath.ForeColor;	var flatness = textPath.Flateness;	const float to_degrees = (float)(180.0 / Math.PI);// SUB: Draws a string that has been fitted to a base curve defined inside the graphicspath// the effect is similar to WordArt in MS Word.  This assumes that there is a curve in the path object.float x, y, dx, dy;	char[] letters = str.ToCharArray();	float fontScale = fnt.Size * fnt.FontFamily.GetCellAscent(fnt.Style) / fnt.FontFamily.GetEmHeight(fnt.Style);	var m = new Matrix();	// break up the smooth curve into a sequence of straight lines (tight curves may become jagged)	gp.Flatten(m, flatness);        // the matrix is just a default one	// upper bound for loop counter	int upper = Math.Min(gp.PathPoints.Length - 2, str.Length - 1);	float scale = 0f;	Brush textBrush = new SolidBrush(clr);	for (int i = 0, loopTo = upper; i <= loopTo; i++) {		x = gp.PathPoints[i].X;		y = gp.PathPoints[i].Y;		// find the normal by swapping the coords and negating the final y value		dx = gp.PathPoints[i + 1].Y - y;		dy = x - gp.PathPoints[i + 1].X;		// change the dx,dy vector into a unit vector ("normalize" the normal)		scale = fontScale / (float)Math.Sqrt((double)(dx * dx + dy * dy));		dx *= scale;		dy *= scale;		m.Reset();		m.Translate(x + dx, y + dy);                // position the character													// rotate the character to align it to the curve		m.Rotate((float)(Math.Atan2((double)dy, (double)dx) * to_degrees + 90d));		g.Transform = m;               // apply the transformation to the g surface		// draw a single character onto the g surface		g.DrawString(letters[i].ToString(), fnt, textBrush, 0, 0);	}	g.ResetTransform();}